effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _SourceTex_TexelSize (1.0 / vec2(textureSize(inputImg, 0)))
vec2 u_xlat0;
int u_xlati1;
float u_xlat2;
vec2 u_xlat3;
vec2 u_xlat5;
bool u_xlatb5;
float u_xlat8;
float u_xlat12;
void main()
{
    u_xlat0.xy = _SourceTex_TexelSize.xy * vec2(vec2(_dilate, _dilate));
    u_xlat8 = float(0.0);
    u_xlat12 = float(0.0);
    for(int u_xlati_loop_1 = 0 ; u_xlati_loop_1<32 ; u_xlati_loop_1++)
    {
        u_xlat12 = u_xlat12 + 0.196349531;
        u_xlat2 = sin(u_xlat12);
        u_xlat3.x = cos(u_xlat12);
        u_xlat3.x = u_xlat0.x * u_xlat3.x;
        u_xlat3.y = u_xlat0.y * u_xlat2;
        u_xlat5.xy = u_xlat3.xy + acScreenNorm.xy;
        u_xlat5.xy = clamp(u_xlat5.xy, 0.0, 1.0);
        u_xlat5.x = texture(inputImg, u_xlat5.xy).w;
        u_xlatb5 = _dilate_threshold<u_xlat5.x;
        u_xlat8 = (u_xlatb5) ? 1.0 : u_xlat8;
    }
    fragColor = vec4(u_xlat8);
    return;
}
